begin;
set local search_path=public,extensions;
select plan(16);
select ok(not has_function_privilege('authenticated','public.customer_email_contact(text,uuid)','EXECUTE'),'contact resolver is not accessible to app users');
select ok(not has_function_privilege('anon','public.customer_email_contact(text,uuid)','EXECUTE'),'contact resolver is not public');
select ok(has_function_privilege('service_role','public.customer_email_contact(text,uuid)','EXECUTE'),'worker can resolve contacts');
insert into auth.users(id,email,email_confirmed_at) values('b1000000-0000-4000-8000-000000000001','owner@example.test',now());
insert into public.workspaces(id,name) values('b2000000-0000-4000-8000-000000000001','Contact test');
insert into public.workspace_members(workspace_id,user_id) values('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001');
insert into public.workspace_settings(workspace_id) values('b2000000-0000-4000-8000-000000000001') on conflict do nothing;
select is(app_private.business_email_contact('b2000000-0000-4000-8000-000000000001')->>'email','owner@example.test','verified account fallback');
select ok(not app_private.business_email_contact('b2000000-0000-4000-8000-000000000001') ? 'phone','never invent a private phone');
update auth.users set email='private@privaterelay.appleid.com' where id='b1000000-0000-4000-8000-000000000001';
select ok(not app_private.business_email_contact('b2000000-0000-4000-8000-000000000001') ? 'email','Apple relay fallback not exposed');
select throws_ok($$update public.workspace_settings set customer_contact_email='not-email' where workspace_id='b2000000-0000-4000-8000-000000000001'$$,'23514',null,'invalid contact email rejected');
select throws_ok($$update public.workspace_settings set customer_contact_phone='-------' where workspace_id='b2000000-0000-4000-8000-000000000001'$$,'23514',null,'phone requires real digits');
update public.workspace_settings set customer_contact_email='business@example.test',customer_contact_phone='+44 7700 900123' where workspace_id='b2000000-0000-4000-8000-000000000001';
select is(app_private.business_email_contact('b2000000-0000-4000-8000-000000000001')->>'email','business@example.test','configured business email wins');
insert into public.booking_requests(id,workspace_id,name,phone,email,status) values('b5000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','Sample','07700 900123','customer@example.test','pending');
select is((public.customer_email_contact('event',(select id from app_private.customer_event_emails where workspace_id='b2000000-0000-4000-8000-000000000001'))->>'phone'),'+44 7700 900123','event has usable direct phone');
update public.workspace_settings set customer_contact_email='updated@example.test' where workspace_id='b2000000-0000-4000-8000-000000000001';
select is((public.customer_email_contact('event',(select id from app_private.customer_event_emails where workspace_id='b2000000-0000-4000-8000-000000000001'))->>'email'),'business@example.test','retry freezes contact for idempotency');
insert into app_private.transactional_email_outbox(workspace_id,booking_request_id,event,recipient_email,payload) values('b2000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000001','booking_request_confirmed','customer@example.test','{}');
select is((public.customer_email_contact('confirmation',(select id from app_private.transactional_email_outbox where workspace_id='b2000000-0000-4000-8000-000000000001'))->>'email'),'updated@example.test','new confirmation uses latest contact');
insert into public.appointments(id,workspace_id,title,start_time,end_time,status) values('b6000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','Visit',now()+interval '1 hour',now()+interval '2 hours','scheduled');
insert into app_private.booking_reminder_preferences(id,workspace_id,email) values('b7000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','customer@example.test');
insert into app_private.booking_reminder_outbox(appointment_id,preference_id,start_time,minutes_before,due_at,expires_at) values('b6000000-0000-4000-8000-000000000001','b7000000-0000-4000-8000-000000000001',now()+interval '1 hour',60,now(),now()+interval '10 minutes');
set local role service_role;
select is((public.customer_email_contact('reminder',(select id from app_private.booking_reminder_outbox where appointment_id='b6000000-0000-4000-8000-000000000001'))->>'email'),'updated@example.test','worker resolves reminder via appointment workspace');
reset role;
select throws_ok($$select public.customer_email_contact('event','ffffffff-0000-4000-8000-000000000001')$$,'P0001','Email intent unavailable','unknown intent rejected');
select throws_ok($$select public.customer_email_contact('invalid','ffffffff-0000-4000-8000-000000000001')$$,'P0001','Unknown email kind','unknown queue rejected');
select set_config('request.jwt.claim.sub','ffffffff-0000-4000-8000-000000000001',true);
set local role authenticated;
select is((select count(*)::integer from public.workspace_settings where workspace_id='b2000000-0000-4000-8000-000000000001'),0,'another user cannot read business contact settings');
reset role;
select * from finish();
rollback;
